def cidr_contains(cidr: str, ip: str) -> bool:
    def parse_ipv4(s: str) -> int:
        if "/" in s:
            raise ValueError
        parts = s.split(".")
        if len(parts) != 4:
            raise ValueError

        value = 0
        for part in parts:
            if not part or any(ch < "0" or ch > "9" for ch in part):
                raise ValueError
            octet = int(part)
            if octet > 255:
                raise ValueError
            value = (value << 8) | octet
        return value

    def parse_cidr(s: str):
        if "/" not in s:
            raise ValueError
        addr, prefix_str = s.split("/", 1)

        addr_int = parse_ipv4(addr)

        if not prefix_str or any(ch < "0" or ch > "9" for ch in prefix_str):
            raise ValueError
        prefix = int(prefix_str)
        if prefix > 32:
            raise ValueError

        return addr_int, prefix

    ip_int = parse_ipv4(ip)
    cidr_int, prefix = parse_cidr(cidr)

    if prefix == 0:
        return True

    mask = (0xFFFFFFFF << (32 - prefix)) & 0xFFFFFFFF
    network = cidr_int & mask

    return (ip_int & mask) == network
